edits.replacement:
#appavatarpicker .costile[data-rar]{ border-top:3px solid var(--rar,#9da3a8); }
/* v28.xx (cw-cosrarthick) 2.79 a: rank also reads in greyscale, the top bar grows 2 to 6px from common to gold */
#appavatarpicker .costile[data-rar="common"]{ border-top-width:2px; }
#appavatarpicker .costile[data-rar="uncommon"]{ border-top-width:3px; }
#appavatarpicker .costile[data-rar="rare"]{ border-top-width:4px; }
#appavatarpicker .costile[data-rar="elite"]{ border-top-width:5px; }
#appavatarpicker .costile[data-rar="gold"]{ border-top-width:6px; }

check:
{v:'VER',what:'fashion tiles show rank by top bar thickness, not only colour (2.79 a)',
 run:function(){
   var host=document.getElementById('appavatarpicker'), tmp=null;
   if(!host){ host=tmp=document.createElement('div'); host.id='appavatarpicker'; document.body.appendChild(host); }
   var w=[];
   try{
     ['common','uncommon','rare','elite','gold'].forEach(function(r){
       var t=document.createElement('div'); t.className='costile'; t.setAttribute('data-rar',r); host.appendChild(t);
       w.push(parseFloat(getComputedStyle(t).borderTopWidth)); host.removeChild(t);
     });
   } finally { if(tmp) document.body.removeChild(tmp); }
   for(var i=1;i<w.length;i++) if(!(w[i]>w[i-1])) return 'bar widths do not grow with rank: '+w.join(',');
   return null; }},
